<?php
session_start();header('Content-Type: application/json');require_once '../config/database.php';require_once 'lib.php';if(!isset($_SESSION['user_id'])){http_response_code(401);echo json_encode(['error'=>'Authentication required']);exit;}try{ttOperationsRequireCsrf();$railroad=ttOperationsRailroad($pdo,(int)$_SESSION['user_id']);$moveId=(int)($_POST['move_id']??0);$complete=($_POST['complete']??'0')==='1'?1:0;$stmt=$pdo->prepare("UPDATE operation_switch_list_moves m JOIN operation_switch_lists sl ON sl.id=m.switch_list_id SET m.progress_complete=?,m.progress_updated_at=NOW(),sl.status=IF(sl.status='approved','in_progress',sl.status),sl.started_at=IFNULL(sl.started_at,NOW()) WHERE m.id=? AND sl.railroad_id=? AND sl.status IN('approved','in_progress')");$stmt->execute([$complete,$moveId,(int)$railroad['id']]);if(!$stmt->rowCount())throw new RuntimeException('Move is not editable.');echo json_encode(['ok'=>true,'complete'=>(bool)$complete]);}catch(Throwable $e){http_response_code(422);echo json_encode(['error'=>$e->getMessage()]);}
